if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[39905] = { id = 39905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ringing True", description = "While your presence here would continue to be of value to us, your master in Dalaran has called for you.\n\nI'd like to thank you again for all you've done for us. My hunters have been reminded that they're not alone in this war.", completion = "{name}, you're back. Excellent work down in Azsuna. Jace gave you high praises for your help with his troops and against the Legion.\n\nBefore you go, I wanted to share with you the other new formulas we have for ring enchantments. It would do our side good in this war if you were to share these with your fellow adventurers.", objectives = "Return to Nalthanis in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39906] = { id = 39906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepping For Battle", description = "To earn my mark, {class}, you must first prove yourself in battle to me. There is a naga I wish to kill, but I am not strong enough to slay him.\n\nBefore we go into battle together, I need your help as an enchanter to become stronger. I'm sure by now you have a bevy of enchantments in your repertoire.\n\nMake some for me so that I may become strong enough again to make a difference in this world.", progress = "Once I have the power I need, we shall test both our strengths.", completion = "<Alynblaze takes the vellums from you and applies them to his gear.>\n\nYes! I feel like I can take on the entire Legion now!\n\nWell, that may be a bit of an exaggeration, but I certainly feel up for some battle.", objectives = "Craft an Enchant Cloak - Word of Strength vellum, an Enchant Ring - Word of Critical Strike vellum and an Enchant Ring - Word of Mastery vellum for Alynblaze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39907] = { id = 39907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elven Enchantments", description = "You have earned the marks of my most trusted companions. You have also returned my love to me.\n\nI am fortunate to have met you, {name}.\n\nNow return to your master and let him know of what you have learned.", completion = "<You tell Nalthanis of your time with the cursed elves and the enchantments you learned.>\n\nThat's fascinating! You managed, through enchantments, to create a bond with those elves and now they may come to your aid?\n\nThose are some truly powerful enchantments you were gifted, {name}. Don't let them go to waste.", objectives = "Return to Nalthanis in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39910] = { id = 39910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Druid's Debt", description = "In order to grant you my mark, {class}, I must first be made strong enough to come to your aid should you need it.\n\nWithin the ruins of Nar'thalas, my idols sit dormant. As I've said, I'm not strong enough to get them myself.\n\nBut you are strong, I can sense it. Strong enough to take on those honor-less naga who plague my home.\n\nFind my idols and return them to me. Do this and I will grant you my mark.", progress = "Have you found them? Are they still intact?", completion = "<Merrus takes the idols from you and clutches them closely to his chest.>\n\nYou've no idea how long it's been since I've held these. Thank you, {name}.\n\nYou have earned my respect and as promised, you shall have my marks.", objectives = "Find Merrus' Idol of the Paw, Idol of the Claw and Idol of the Moon and return them to him at the Crumbled Palace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39914] = { id = 39914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sentinel's Final Duty", description = "Now that I'm stronger, it's time to test your mettle, and mine. As I mentioned earlier, there is a powerful naga I wish to kill.\n\nHis name is Fathom-Commander Eksis. He was responsible for slaying many of my kin before he retreated into hiding, commanding his troops from the shadows.\n\nI've finally discovered his whereabouts in a cave just east of here. Let us bring vengeance upon him for my lost brothers and sisters.", progress = "He will rue the day he ever set foot upon my homeland.", completion = "You fought bravely, {name}. I see that you truly are worthy of my marks and I hereby grant them to you.\n\nPerhaps one day we shall stand again side by side in battle.", objectives = "Slay Fathom-Commander Eksis. Return to Alynblaze at the Crumbled Palace when you are through.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39916] = { id = 39916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turnabout Betrayal", description = "Enchantress Ilanya remembers me?\n\n<The satyr pauses to wipe a tear away.>\n\nI made a fool's bargain ten millennia ago. I learned of the queen's alliance with the Legion and betrayed my heart to join their side. I was transformed into a monstrosity, only to die in battle against the mortals.\n\nNow the Legion returns, but I linger as an impotent spirit. Be my vessel and slay the demons ahead of us. Take their demonic runes and render them to dust.", progress = "The death screams of the Legion bring me some semblance of joy.", completion = "After watching these demons helplessly for so long, you have given me a chance to strike back at them!\n\nNow the real work begins.", objectives = "Defeat demons at the Felblaze Ingress. Take their Fel-crusted Runes and disenchant them into 5 Dust of Foul Lies. Return to where you met the Fallen Priestess when you are done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39918] = { id = 39918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Absent Priestess", description = "After my betrayal, I never thought I could bear to look upon my love again. But thanks to you, {name}, I can at last return.\n\nGo and speak to Enchantress Ilanya. I will let her know that you are worthy of my mark.", completion = "You have returned my love to me and for that I am forever grateful.\n\nAs she is with me now, she shall be at your beck and call should you need her. I grant to you her marks.", objectives = "Return to Enchantress Ilanya at the Crumbled Palace in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39920] = { id = 39920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Azure Wings", description = "I have some exciting news of my own to report, {name}. Ildine and I had an excursion to Azsuna and made contact with the blue dragons at the Azurewing Repose.\n\nOne of the dragons, Kharmeera, is an enchanter who expressed interest in working with you to perfect some of our enchantments.\n\nI understand you were just down there working with the elves, but if you wouldn't mind returning, Kharmeera would enjoy working with you too.", completion = "I sense the power of enchantments about you, {name}. Yes, I think I will enjoy working with you!", objectives = "Speak to the dragon Kharmeera at Azurewing Repose in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39921] = { id = 39921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Lair: Rod of Azure", description = "Before we can begin though, there is a small favor I need to ask of you. I'm rather ashamed about this matter, to be honest, but it must be done in order for us to work together.\n\nWhen I was summoned to this land, I hadn't been given a chance to collect my things. Most importantly, I left behind my enchanting rod.\n\nInstead of retrieving it I believe it would be much simpler to reconstruct it.\n\nHere's what we'll need...", progress = "How goes the hunt for the rod components?", completion = "Oh yes, that seems to be everything.\n\n<Kharmeera takes the components from you and assembles the rod.>\n\nNow, let's see what I can share with you.", objectives = "Retrieve a Skystone Rod from Dargrul the Underking in Neltharion's Lair, a Radiant Zephyrite from Ozruk in The Stonecore and a pile of Ancient Arkhana from Scholomance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39923] = { id = 39923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down to the Core", description = "The ring enchantments you know now are good, but I know of better ones that exist. That is to say, I know of stronger enchantments that would be suitable for rings.\n\nAccording to legend, there are four constructs whose cores were imbued with magical enchantments. These constructs now patrol the streets of Suramar City.\n\nIf you were to gather some friends and defeat these constructs, you could take their cores for us to study.", progress = "Remember to bring some friends with you, those constructs are incredibly powerful.", completion = "I'm truly amazed at what you're able to accomplish for such a young creature.\n\nShall we get to work then on learning from these cores?", objectives = "Retrieve the Power Cores from Oldus, Or'ell, Olmoore, and Oll'ison. Bring them back to Kharmeera when you have all four.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39925] = { id = 39925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary Azathar Looted" }
quests[39926] = { id = 39926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Malus Looted" }
quests[39927] = { id = 39927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wingterror Ikzil Looted" }
quests[39928] = { id = 39928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uther's Spirit Honored" }
quests[39929] = { id = 39929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uther's Spirit Honored" }
quests[39930] = { id = 39930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uther's Spirit Honored" }
quests[39931] = { id = 39931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smashing Herbs", description = "Now that the formalities are out of the way, let's have you do something actually useful.\n\nOn the islands below, there's a plethora of new and exotic herbs that we've yet to experiment with.\n\nI'd like you to get some of those herbs and create some new pigments from them. Once you have enough, come back to me and I'll see what you've come up with.", progress = "Well? Do you have the pigments, or are you just wasting my time?", completion = "Yes, these pigments look like they will do the trick. Well done, student.\n\nIn fact... I've been researching a new glyph that these pigments would work splendidly with. Why don't you give it a shot?", objectives = "Obtain 20 Roseate Pigments and 2 Sallow Pigments. Pigments are obtained by milling herbs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39932] = { id = 39932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Ink", description = "You know, herbs aren't the only ways to obtain ink. Other materials can be inkified.\n\nSlightly related! I've been tinkering with the idea of creating my own type of Darkmoon card. Surely if those troggish carnival people can do it, then so can I.\n\nTo do so, we'll need some special reagents. Go down to Azsuna and collect some oils for me, then mill them into a suitable ink.", progress = "My pigment?", completion = "Holy mackerel! This stuff really puts the \"ink\" in \"stink\", doesn't it?", objectives = "Obtain 5 Mak'rana Oil, 5 Hatecoil Naga Oil, and 5 Salteye Oil, then combine them into a Piscine Pigment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39933] = { id = 39933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Card Shark", description = "We have the pigment, but we still require one more ingredient.\n\nVisitors at the Legerdemain Lounge will often play card games, and occasionally their cards are discarded. Go see if you can find some loose cards that players may have gotten rid of between matches.", progress = "The cards are just for reference, mostly...", completion = "And there we have it. Just as good as those witless Darkmoon cretins.\n\nWhile we owe this success almost exclusively to my genius, I feel you ought to be rewarded for doing the legwork. Here's the recipe for my newest masterpiece.", objectives = "Collect 10 Hearthstone Cards at the Legerdemain Lounge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39934] = { id = 39934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our New Allies", description = "Have you seen those demon hunters yet? I'm not entirely sold on their allegiance to our cause, but while we have them, we may as well exploit them.\n\nEverybody needs glyphs, you know.\n\nGo see what you can discover about them. Azsuna is as good a place as any to start.\n\nPerhaps my genius has worn off on you and you'll be able to create your own recipes based on what you learn.", completion = "Are you here to reinforce us, {class}? We could always use your strength.", objectives = "Go to Azsuna and find Allari the Souleater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39935] = { id = 39935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Price of Power", description = "You wish to learn what it is to be a demon hunter? That may take some time.\n\nThe first thing you can do is fight alongside us. Battle the demons with us and observe how we use their strength against them.\n\nReturn to me when you are finished.", progress = "Have you seen enough?", completion = "Some may condemn our methods. We simply do what we must to destroy the Burning Legion.", objectives = "Slay 15 demons at Illidari Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39936] = { id = 39936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inscription of the Body", description = "We demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves. That is the purpose of marking our skin the way we do.\n\nUp to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. Go to him and learn how we keep our demons at bay.", completion = "Allari sent you? I am about to start a ritual. I could use you, stranger.\n\nYou seem more ally than enemy. In this time, allies are more important than ever.", objectives = "Find Baric Stormrunner near the Ley-Ruins of Zarkhenar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39937] = { id = 39937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opposites Repel", description = "There's a balance that must be struck, {name}, when becoming a demon hunter. In order to maintain that balance, we must infuse ourselves with opposite forces of nature.\n\nFel energy is counteracted by arcane energy. We mark our bodies with arcane runes to keep our fel forces in check.\n\nYou are a scribe, yes? Then you should have no trouble mixing a suitable ley pigment from the ley dust on the creatures in the ruins up ahead.", progress = "Even though they are opposites, one can not exist without the other.", completion = "If you can believe it, that was the easy part. The next part will be a bit more challenging\n\n...at least, for me it will.", objectives = "Collect 10 Ley Dust from the nightfallen and withered in the Ley-Ruins of Zarkhenar, then mix it into a Ley Pigment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39938] = { id = 39938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containing the Demon Within", description = "Now that we have all the essential pieces, let's begin the ritual.\n\nI'll instruct you on how to help me. It is pivotal that you follow my instructions when I give them, or the ritual will fail.", completion = "It is done. I fear that if I had waited any longer to improve my wards, the demon in me may have taken over.\n\nThank you again, {name}.", objectives = "Assist Baric in completing the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39939] = { id = 39939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scribal Knowledge", description = "We do not simply fight the demons, {name}. We observe them.\n\nOne of my best demon hunters, Zaria Shadowheart, is currently gathering intel on the demons in Felblaze Ingress.\n\nGo to her. She will teach you what she has learned from the demons invading that region.", completion = "Allari has sent you to learn from me? In that case, I have much to tell.", objectives = "Find Zaria Shadowheart near the Felblaze Ingress in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39940] = { id = 39940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runes of Power", description = "Look closely, scribe, and you may learn. As the demons spread out over a region, the more clever ones will inscribe runes upon the ground. The fel taint pervades this entire hillside, but the corruption is darkest around these runes, disallowing anything pure to grow ever again.\n\nStudy these runes.", completion = "As I'm sure you sensed, these runes hold quite a bit of energy.\n\nGreater knowledge of the Legion is your best weapon against it.", objectives = "Study 8 Fel Power Runes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39941] = { id = 39941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Control is Key", description = "We demon hunters ritualistically remove our eyes in order to see the demons more clearly.\n\nDown below, a demon commander walks amongst his troops, unseen by normal eyes. He keeps the chaos in order, as we must keep our chaos in check.\n\nDestroy his warding crystal, then slay him.", completion = "I commend you, scribe. You would make an excellent demon hunter.\n\nTake this ink as payment for your efforts. I have no need of it.", objectives = "Destroy the crystal protecting Overseer Felorax, then slay him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39942] = { id = 39942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aethrem Crystal", description = "<Most aethril has a sharp crystalline fiber in the center of the bloom, but this one is particularly well-developed.>\n\n<Professor Pallin would be interested in seeing this.>", completion = "A crystal... inside the flower? That gives me an idea.\n\nI dabbled in jewelcrafting in my younger years. Take a look at this technique...", objectives = "Bring the Aetherem Crystal to Professor Pallin in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39943] = { id = 39943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burdens of Hunting", description = "There is nothing more I have to teach you, scribe. The Illidari stand behind you in the battle against the Legion.", completion = "<Professor Pallin looks over the demon hunter glyphs you've designed.>\n\nHuh! Apparently I don't have to hold your hand as much as I thought.\n\nLook at this glyph you've made right here. If you flip this symbol around, and adjust the stroke width here...", objectives = "Report back to Professor Pallin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39944] = { id = 39944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Messages", description = "The woman at the archaeology shop just dropped off some tablets to be deciphered. Any fool can see they're written in ancient vrykul, but I lent my codex to one of my students, so I'm unable to decipher them here.\n\nHis name is Nicholo Swiftfuse, and he is in Stormheim. Let him know that if he fails to decipher them, his apprenticeship shall be terminated.\n\nThat is all.", completion = "Seriously? Pallin wants me to do what now?!\n\nThat old bag of wind thinks he's so great, but he's always making me do all his work. It's a surprise I'm not running that shop.\n\nBut fine, I'll help you. As long as you help me too.", objectives = "Deliver the tablets to Nicholo Swiftfuse in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39945] = { id = 39945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runes Within the Ruins", description = "Unfortunately, Pallin's codex isn't complete. There are many symbols here that simply cannot be deciphered with what we've learned.\n\nLooks like we'll need to go and collect more tablets down in the area that the vrykul call Haustvald.", progress = "We need those tablets if we're to progress any further in deciphering their language.", completion = "I believe these have enough information for us to finish the codex. Excellent work, {name}.\n\nIf you don't mind me saying, it's nice to finally not be the one running errands.", objectives = "Collect 10 Ancient Vrykul Rune Tablets within Haustvald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39946] = { id = 39946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right Tool for the Job", description = "From what little I have been able to decipher, I know that the tablets are created using a special carving tool.\n\nIf we had one of those tools, along with a complete codex, we could easily create our own tablet.\n\nThat would also serve to prove that my deciphering of their language has been successful.\n\nRetrieve one of those tools for me, {name}.", progress = "The knife is the final key to my research. Any luck finding one?", completion = "Wow. It's much... bigger than I had expected.\n\nThen again, vrykul are very large and I'm... well, I am not.\n\nStill though, I believe I can work with this.", objectives = "Acquire a Runic Bone Knife.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39947] = { id = 39947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not So Complex?", description = "Alright, I believe I've finished adding the missing entries into the codex. And we have the machete... err, knife.\n\nAll that's left is to make our own tablet and verify my other suspicion about these tablets:\n\nI believe that they're not just simple texts, but a sort of magical device.", completion = "It was a good thing you were here to help me with that.\n\nI surely would have been killed by those spirits!", objectives = "Assist Nicholo with the creation of a rune tablet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39948] = { id = 39948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ink Flows", description = "{name}, I need you to make a quick delivery for me.\n\nYes, I've learned by now that such trivial tasks are beneath your skills... but I'm rather busy right now and we both know my time is much more important than yours.\n\nDeliver these contracts to Raethan, the Guard Captain in Dalaran's Underbelly.", completion = "These all seem to be in order.\n\nIf you have a moment, scribe, I have a proposition for you that you may be interested in...", objectives = "Deliver the contracts to Raethan in the Underbelly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39949] = { id = 39949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once a Scribe Like You", description = "These sewers are something of a... \"settling place\" for many who can't cope with the stresses of regular Dalaran life. Take, for example, the target of this particular contract.\n\nHis name is Inkrot. He was once a scribe like you, but the stresses of dealing with the Professor drove him mad.\n\n<Raethan hands you the contract.>\n\nThis says he's stolen a jewel from Cartier and Co. Bring me the jewel. Whatever else you find on him is yours.", progress = "Did he give you much trouble?", completion = "You, {name}, are a godsend. I thought I'd never be rid of that nuisance.\n\nAs promised, here is the bounty for the contract.", objectives = "Kill Inkrot and obtain the Stolen Shadowruby.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39950] = { id = 39950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Odd Trinket", description = "Wait, {name}, before you leave... did you not notice this?\n\n<Raethan peels a small piece of paper from the bottom of the jewel.>\n\nThis wasn't reported stolen. It appears to be a card of some kind. Must be a scribe thing.\n\nPerhaps it may be of some use to you.", progress = "What's that you have there?", completion = "I... I know this work. My old apprentice, what's-his-name, was trying to prove he could create something as great as I could.\n\nImpressively, he seemed to have succeeded in this one case.\n\nWe should learn from what he created and make our own, less putrid version.", objectives = "Give the Rotting Tarot Card to Professor Pallin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39951] = { id = 39951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roseate Essence", description = "<The pigment milled from this flower is of an exceptionally high quality.>\n\n<Professor Pallin would be interested in seeing this.>", completion = "How did you get an extract so pure? Show me exactly what you did, step by step.\n\nFascinating. Do you mind if I write this down, so I can show my other students?", objectives = "Bring the Roseate Essence to Professor Pallin in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39952] = { id = 39952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sallow Essence", description = "<The felwort is reduced to a thick, clotted pigment. While all felwort-begotten pigment is somewhat offensive, this batch practically glows with a malevolent energy.>\n\n<Professor Pallin would be interested in seeing this.>", completion = "We've ventured into undiscovered territory, {name}. There isn't anyone out there in ANY academic circles I'm aware of that is milling felwort this effectively.\n\nWell done, student. Or, should I say... well done, junior deputy assistant scribe?\n\nNah... I still prefer \"student\".", objectives = "Bring the Sallow Essence to Professor Pallin in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39953] = { id = 39953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: Vision of Valor", description = "I think it's time for another field trip, {name}. To the Halls of Valor!\n\nThe Valarjar are masters of all types of runecraft. Perhaps we can find something useful for a new recipe.", progress = "Did you see any gods while you were there?", completion = "My stars... these are very nice indeed! In fact, this gives me an idea...", objectives = "Retrieve 5 Valarjar Rune-Sigils from the Halls of Valor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39954] = { id = 39954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mass Milling Techniques", description = "A number of my previous students have been vocal in their displeasure regarding milling. They find the process \"repetitive\", \"mindless\", and even \"painful\". Have they no respect for the time-honored traditions of inscription?\n\nI suppose you count yourself among their number. Am I right? Very well. You've been a fine student so far, so I suppose there's no harm.\n\nI have a book about mass milling somewhere around the shop here. Find it, and it's yours.", progress = "Try not to make too big a mess.", completion = "That's it! Hmm... let's see...\n\n<Pallin looks quickly through the pages of the old book.>\n\nNot much in here that will help you with our Broken Isles herbs.\n\nWait, hold that thought. Look at this here...", objectives = "Find The Masterful Miller's Manual in Dalaran's inscription shop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39955] = { id = 39955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plot Thickens", description = "Very well, I won't deny it. The Steamy Romance Novel is mine.\n\nI only read it for the penmanship, I assure you! He writes such curvy \"B\"s... and such ample \"D\"s!\n\nIn fact... you might benefit from a penmanship lesson. The author of these books is one B. Spearshaker. I believe he can be found in the library in Ironforge.\n\nStop reading, student. You are dismissed. And give me my book back!", completion = "Hello! Ye must be one of me many fans here for an autograph.\n\nOh, yer here about the romance novels, are ye? I see ye've discovered my little secret.\n\nYe know, I've grown tired of writing those. I've moved on, ye see. Wrote me last one yesterday.\n\nBut perhaps ye'd like to carry on the tradition...?", objectives = "Go to Ironforge and look for B. Spearshaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39956] = { id = 39956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legacy Passed On", description = "I've lost my passion, scribe. I just can't get into the voice o' the characters anymore.\n\nTake a look at that unfinished book over there on the table. I can't seem to finish it. Maybe ye'll have an easier time with it.", progress = "Dang-blasted writer's block!", completion = "Hmm... yes, ye seem to have gotten the hang of it. I particularly like that line: \"Oh, Lord Gravesbane!\" That would make a nice catchphrase...\n\nHere, take this list o' story prompts. I certainly don't need them anymore.", objectives = "Complete the Unfinished Steamy Romance Novel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39957] = { id = 39957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon Ink", description = "These sigils would make for a fantastic new tarot card. Quite powerful, in fact. We simply require an ink sturdy enough to inscribe them.\n\nFortunately, I have students like you that excel at fetching hard-to-get items.\n\nFor this project, I require ink mixed from demonic blood. The blood of the demons at Felsoul Hold will serve as a suitable base. You will also need Blood of Sargeras, of course.", progress = "If you're unsure where to get demon blood, go to Suramar and look around. You're bound to trip on a demon sooner or later.", completion = "This is more than enough. Excellent work!\n\n<Professor Pallin produces a small quill, dips it in the ink and begins scribbling on a small card.>\n\nJust as I thought, easy enough to make.\n\nAs is usually the case with tarot cards, you'll have to make a complete set in order for them to yield their full potential.", objectives = "Collect 25 Vials of Felsoul Blood and 1 Blood of Sargeras, then mix them into Felsoul Ink.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39958] = { id = 39958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skin Deep", description = "Welcome, {name}. It's an honor to be working with someone of your caliber.\n\nIn order for us to begin our work together, we'll first need to collect some materials.\n\nThe Broken Isles are home to many strange, exotic creatures which no doubt have interesting hides to experiment with. We'll need scales to make mail armor with as well.\n\nGo and collect some materials for us so we may begin working.", progress = "I trust you gave the creatures a merciful death?", completion = "These materials have my mind racing. I can't wait to see what we can make with them!\n\nI'm just going to keep some to study. You can have the rest back.", objectives = "Acquire 20 Stonehide Leather and 5 Stormscales. If you are not a skinner, you may acquire them from the auction house or other players.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39959] = { id = 39959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plot Thickens", description = "Very well, I won't deny it. The Steamy Romance Novel is mine.\n\nI only read it for the penmanship, I assure you! He writes such curvy \"B\"s... and such ample \"D\"s!\n\nIn fact... you might benefit from a penmanship lesson. The author of these books is one F. Serbacon. I believe he can be found in the library in Undercity.\n\nStop reading, student. You are dismissed. And give me my book back!", completion = "Come for an autograph, have you? Very well, you may present your chest to me.\n\nOh, you're here about the romance novels? I see you've discovered my little secret.\n\nYou know, I've grown tired of writing those. I've moved on, you see. Wrote the last one yesterday.\n\nBut perhaps you'd like to carry on the tradition...?", objectives = "Go to the Undercity and look for F. Serbacon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39960] = { id = 39960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legacy Passed On", description = "I've lost my passion, scribe. I just can't find the voice of my characters anymore.\n\nTake a look at that unfinished book over there on the table. I can't seem to finish it. Maybe you'll have an easier time with it.", progress = "Confound this accursed writer's block!", completion = "Hmm... yes, you seem to have gotten the hang of it. I particularly like that line: \"Oh, Lord Gravesbane!\" That would make a nice catchphrase...\n\nHere, take this list of story prompts. I certainly don't need them anymore.", objectives = "Complete the Unfinished Steamy Romance Novel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39961] = { id = 39961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Embarrassing Revelation", description = "This doesn't appear to be an inscription textbook at all... it's more of a steamy romance novel. The pages are just FILLED with tawdry tales of carnality.\n\nCould it have something to do with inscription? Either way, Professor Pallin should be confronted.", completion = "Get your hands off of... err, I mean... that's not my...\n\nWhere did you...\n\n<The professor makes a sputtering sound.>\n\nSomeone must be playing a trick on me!", objectives = "Bring the Steamy Romance Novel to Professor Pallin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39962] = { id = 39962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble for Okuna", description = "<You open the bottle and find a message inside.>\n\nHelp! I need somebody... but not just anybody. I need a champion! I finally escaped the grasp of Prince Oceanus only to be hunted by his father, King Deepbeard.\n\nI was enjoying my freedom and decided to go fishing when that giant attacked. I've been running around these islands trying to avoid that creature ever since... if anyone gets this message, please send help!", objectives = "Search for Okuna Longtusk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39963] = { id = 39963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abandoned Fishing Pole" }
quests[39964] = { id = 39964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinerock Basin Treasure" }
quests[39965] = { id = 39965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvan Falls Treasure" }
