quests[39978] = { id = 39978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the Recruits", description = "Highlord, my mission in Dalaran was successful. I have recruited paladins truly worthy to carry your banner.\n\nThey await your return at the Sanctum of Light.", objectives = "Use the Guiding Light spell to return to Light's Hope Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39980] = { id = 39980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highlord Darion Mograine Slotted" }
quests[39981] = { id = 39981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thassarian Slotted" }
quests[39982] = { id = 39982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koltira Deathweaver Slotted" }
quests[39983] = { id = 39983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huln's War - The Arrival", description = "Huln Highmountain is the origin of our strength as a tribe. He bested the Legion when last they threatened our survival and unified many disparate tribes.\n\nLive his story, and you will know why his name imbues courage in the cowardly and sows fear in the fearless.", completion = "[In broken Common] Feathered one said you come. Unng Ak not hope for you come. Tauren have thanks.", objectives = "Defeat 25 Legion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39984] = { id = 39984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of the Past", description = "<The journal entry appears hastily written.>\n\nI do not know what has become of my village. Ever since the mists engulfed the harbor, my kinsfolk have changed.\n\nSome have grown violent and savage, while others have fallen into madness. Many have ventured into the mists and have yet to return.\n\nIn these times, we can usually turn to our leader, Jarl Tarben. Alas, the mists have taken him as well.\n\nI do not know what will become of me. For now, I can only stay at my post and remain vigilant.", completion = "The mists of this bay rot not only the wood of the ships, but the very souls of its inhabitants.\n\nBut it seems you have already discovered this.", objectives = "Locate clues to discover the fate of Tideskorn Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39985] = { id = 39985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgar's Discovery", description = "Champion! Please come to the Violet Citadel immediately.\n\nI have made a discovery that I would like to share with you before the Council of Six.", completion = "Thank you for coming, {name}.", objectives = "Speak with Archmage Khadgar in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39986] = { id = 39986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magic Message", description = "For the last 10,000 years, the elven city of Suramar has been sealed in an arcane barrier, much like Dalaran once was.\n\nThat barrier has come down.\n\nSince then, waves of magical energy have been emanating from the city like ripples in a pond. It was in these waves that I sensed a pattern.\n\nA spell, encrypted among the chaos.\n\nI have recreated the spell here. It's not dangerous, but beyond that... I have no idea what it does!", progress = "Go ahead and take a look.", completion = "A magical message in a bottle, slipped right beneath the Legion's nose... Clever.", objectives = "Examine the Arcane Anomaly in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39987] = { id = 39987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trail of Echoes", description = "The Nightborne could prove powerful allies against the Legion. We must aid this Thalyssra if we can.\n\nWe should be able to find her by tracking her magical echoes, the same way I found her distress call.\n\nI can teleport you near the location where she recorded that message. From there, you must search for ripples in the very fabric of the arcane itself.\n\nMy wand should do the trick. Follow the sparks it creates--they should lead you to places where Thalyssra used her magic.", progress = "Who are you?", completion = "An outlander...\n\nYou received my message?", objectives = "Use Khadgar's Wand to find Arcane Echoes and track down First Arcanist Thalyssra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39988] = { id = 39988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huln's War - Stormrage", description = "<Eche'ro nuzzles your hand and turns around. It looks back, beckoning you to the south.>", completion = "You bring with you Eche'ro, and... what is this? The blessing of Cenarius?!", objectives = "Meet Malfurion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39989] = { id = 39989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keepers of the Hammer", description = "High Chieftain Ulan has requested your presence.\n\nWe have learned that the Burning Legion has returned and know that if you are true in your purpose in facing this evil, you will need our aid.\n\nOur people have in our possession a great titan relic: the Hammer of Khaz'goroth.\n\nWe intend to lend it to you for this task.\n\nWhen you are ready, join me at our stronghold of Thunder Totem in Highmountain.", objectives = "Meet the High-Chieftain at Thunder Totem in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39990] = { id = 39990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huln's War - Reinforcements", description = "Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle. I would speak with you on this later. It is a rare gift indeed.\n\nBut now, I ask for your help, Huln Highmountain. I must finish my incantations to allow dryads from beyond the veil to enter this place and lend us their aid.", progress = "This shouldn't take long. Please do not allow them to interrupt my spell.", completion = "The ritual is complete. Reinforcements will be able to push through the portal and assist against the demonic horde.", objectives = "Defend Malfurion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39991] = { id = 39991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Cenarius", description = "Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle.\n\nSpeak with him in the grove to the south.", sourceObjective = "Meet with Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[39992] = { id = 39992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huln's War - The Nathrezim", description = "I am fully occupied here organizing my troops and planning for the battle to come.\n\nWhile I would like to slay the Dreadlord Tichondrius myself, I will allow that honor to be yours, Huln Highmountain.", completion = "You see now, that Huln was mighty? He united the tribes and defeated terribly powerful foes.", objectives = "Defeat Tichondrius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39993] = { id = 39993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abandoned Fishing Pole" }
quests[39994] = { id = 39994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crab Rider Grmlrml" }
quests[39995] = { id = 39995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rockaway Coast Treasure" }
