quests[39998] = { id = 39998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drive Back the Tideskorn" }
quests[39999] = { id = 39999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rockaway Coast Treasure" }
quests[40000] = { id = 40000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A True Hunter", description = "I don't know why Hemet hunts with Razik. His contraptions are unreliable at best! \n\nA true hunter doesn't need gadgets to hunt. They rely on instinct, skill, and agility.\n\nSo tell me, {name}, do you have the skills of a true hunter? Better yet, prove it.\n\nTake down some of the Bonebeak Hawks that circle the nearby meadow.", progress = "You can't be huntin' hawks if you're here chattin' at me.", completion = "Now that's how a real hunter does it.", objectives = "Prove you're a worthy hunter by hunting Bonebeak Hawks in Sunfrost Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40001] = { id = 40001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knocking on Valor's Door", description = "The Halls of Valor is your destiny to claim, but it is already in the claiming. The God-King befouls its steps with demons and wickedness.\n\nYour dragon allies have come to Halls' defense, but they need your aid. The vrykul have taken the leader of the storm dragons, the one you call Vethir.\n\nFree your dragon friend, champion, and wash the Felskorn from the Gates of Valor!", completion = "What is this... I see? \n\nA friendly face... in a sea of foes?", objectives = "Find Vethir in the Felskorn Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40002] = { id = 40002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Familiar Fate", description = "We had come to defend the Halls of Valor... I was taken from the sky...\n\nI cannot break free of my bindings. Find the jailer who made this cell...\n\nSet me free, friend...", progress = "The jailer has... the key...", completion = "You still manage to surprise me, outsider. Your trials are complete, and yet you still have challenges to face. \n\nThe God-King's forces are many, but in your weapon you possess the powers of Stormheim herself! Approach the gates, and these powers will lay low the enemies of this land!\n\nNow, let us take the fight to the God-King, and cleanse the Gates of Valor of his fel taint!", objectives = "Collect the Jailer's Shard from Dravax and free Vethir from his prison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40003] = { id = 40003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stem the Tide", description = "Skovald has profaned the Gates of Valor with his demonic allies. Among his forces his twisted mystics have conjured portals to ferry his fel allies from their blighted worlds. \n\nIf we wish to stem this tide, these portals must be destroyed. \n\nI will gather my allies. Take this horn and signal when you have found a portal, and we will strike from the skies!", progress = "The portals must be closed if we wish to stop Skovald's forces!", completion = "I do not understand, the portals are closed and yet Skovald's demonic forces still assault the gates! \n\nWe must find where they are coming from!", objectives = "Use the Stormforged Horn to destroy the three Felbound Portals in Gates of Valor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40004] = { id = 40004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break the Spine", description = "To lead his tainted forces,  the God-King has enlisted demons of great power to act as his lieutenants. If we wish to end his assault, we will need to take their leaders.\n\nThese demons are too powerful for most mortals to face, but with the power of Stormheim at your disposal, they will prove no match for you. \n\nTake them down, and shatter the spine of Skovald's offensive!", progress = "Are the leaders slain?", completion = "With their fel leaders slain, the God-King's forces will scatter. \n\nStill, we are not finished here. So long as the demons continue to assault the gates, Stormheim will not be safe.", objectives = "Defeat Garzareth, Karuas, Muorg and Ravathes in Gates of Valor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40005] = { id = 40005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormheim's Salvation", description = "It would seem that the portals we destroyed down here were not the only ones. Demons still pour in from the top of the Gates of Valor's edifice, summoned by the God-King himself!\n\nI cannot face Skovald alone. Come, champion, let us take the battle to him and end this threat!\n\nFor Stormheim!", completion = "It's unfortunate that the God-King escaped, but his defeat has stemmed the flow of the Legion into Stormheim.\n\nNow, the Halls of Valor await you.", objectives = "Defeat God-King Skovald in the Gates of Valor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40006] = { id = 40006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvan Falls Treasure" }
quests[40007] = { id = 40007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fields of An'she Treasure" }
quests[40008] = { id = 40008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Way Out is Through", description = "I have much to tell you, but it is not safe to speak here. I cannot hold this barrier forever.\n\n<Thalyssra lifts a delicate flask to her lips. Her eyes shimmer as she takes a sip.>\n\nIf we push through, we may find shelter up ahead.", progress = "There is no turning back.", completion = "You fight well.\n\nPerhaps it is time for a proper introduction.", objectives = "Escort Thalyssra to safety.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40009] = { id = 40009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Thirst", description = "My people have subsisted on the Nightwell for millennia. Ancient mana is our lifeblood - without it, we become... well, you saw them out there.\n\n<Thalyssra holds her flask aloft, gently shaking free the last precious drops.>\n\nI'm afraid I have been rather reckless today. \n\nAlready, my senses are dulling. Without magic to feed upon, I will turn. \n\nPlease... find me something to feed upon... anything...", progress = "<Thalyssra's eyes have dulled and her body is shaking uncontrollably.>", completion = "<Thalyssra takes the crystals with a trembling hand.>", objectives = "Enter Shal'Aran and find something to sate Thalyssra's thirst.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40010] = { id = 40010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tapping the Leylines", description = "The arcways were built to tap into the magical leylines beneath Suramar. As we learned to subsist on the Nightwell, the old facilities fell out of use.\n\nThis chamber is clearly receiving power from elsewhere.\n\nThere is only a trickle now, but if you can direct more leyline energy here it will help to sustain us.\n\nThe closest source is to the north, near Anora Hollow.", completion = "And just who might you be?", objectives = "Explore Anora Hollow and find the Ley Station there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40011] = { id = 40011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oculeth's Workshop", description = "We need to make contact with Chief Telemancer Oculeth, the man who developed Suramar's teleportation network. \n\nOculeth had a workshop in old Suramar, from the age before the Sundering. He may be taking refuge there.\n\n<Thalyssra presses a small coin into your palm.>\n\nIf you find him, show him this. Hopefully you see him before he sees you...", progress = "If we are to put up any resistance against the combined forces of the Legion and the Grand Magistrix, we must secure a means of traversing the region quickly.", completion = "You may deliver me to Thalyssra once my work here is complete.", objectives = "Give the First Arcanist's Token to Chief Telemancer Oculeth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40012] = { id = 40012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Ally", description = "I was on my way to Ambervale in hopes of finding an old colleague.\n\nArcanist Kel'danath was fascinated by the withered. He studied them for years hoping to calm their feral nature or even cure them.\n\nWhen one of his subjects escaped and ran amok in the royal gardens, Kel'danath was ordered to cease his research and kill all withered in his possession. He refused, and was exiled.\n\nIf Kel'danath lives, he is near withered. And withered are drawn to old settlements like Ambervale.", completion = "<Somebody has been living here recently. This scroll bears strange lettering that glows warmly, beckoning your hand.>", objectives = "Find Arcanist Kel'danath's hideout in Ambervale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40013] = { id = 40013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aethril Sample", description = "This herb has clearly been absorbing magical energy from the land. Filaments of ley energy course from root to leaf.\n\nYour herbalism trainer in Dalaran will want to see this.", completion = "From the look of it, I would expect such an herb to be fragile and delicate, but... it's quite sturdy.\n\nOooh, look at these!", objectives = "Bring the Aethril Sample to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40014] = { id = 40014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spayed by the Spade", description = "The stem, leaves, and petals are dazzling, to be certain... but look at the pollination filaments, here, and the reproductive organs in the center of the bloom. They contain more energy than the rest of the plant put together.\n\nI suspect that we can more responsibly and efficiently harvest aethril by focusing on these parts.\n\nStill, it looks like this bloom has been damaged. I need undamaged parts if I'm to be sure.", progress = "It may seem wrong to remove these most... \"intimate\" flower parts, but do not fret. They will grow back.\n\nMuch like the parts of a troll.", completion = "<Your trainer looks over the pistil and stamen, clearly impressed.>\n\nThe Earthmother must have been feeling generous when she created the aethril.\n\nContinue to focus on this part of the flower, {name}.", objectives = "Obtain a Pristine Pistil and a Stainless Stamen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40015] = { id = 40015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ragged Strips of Silk", description = "Finely made strips of clothing, torn, tattered, and dirty: telltale signs of the withered.\n\nThe feral, degenerate outcasts of nightborne society must also be harvesting the aethril... but why?", completion = "You found withered implements near an aethril bloom?\n\nHmm... you're the third one today.", objectives = "Speak with Kuhuine Tenderstride about aethril and the withered.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40016] = { id = 40016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperation Breeds Ingenuity", description = "I believe we may be able to use this clue to our advantage, {name}.\n\nThe withered are notoriously thirsty for mana, and will stop at nothing to get it. Perhaps we can study how they use the aethril and use the results to improve our own harvesting methods.", progress = "I am glad you continue to come to my shop, {name}. I am useless with a weapon. We need adventurers like you to solve cases like this.", completion = "<Your trainer examines the stems, fingering the individual bite marks.>\n\nIf you'll pardon my language, they really gnawed the crap out of these things.\n\nLook more closely, though. You can see that they focused on extracting the energy from the stem's central filament...", objectives = "Obtain 6 Chewed Aethril Stems from Withered in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40017] = { id = 40017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Slip of the Hand", description = "As you harvest the aethril, your hand brushes the flower's pollinating organs against one another, creating a reaction.\n\nYou may have discovered a new herbalism technique. Your trainer in Dalaran would be a good person to discuss this with.", completion = "<Kuhuine listens to your story about the aethril.>\n\nWhat you're saying rings true, {name}. I have heard tales of herbalists that could coax flowers into quickly reproducing, but I was never able to master the technique myself.\n\nWell done, herbalist. I feel great pride.", objectives = "Speak with Kuhuine Tenderstride about the quick-reproducing property of aethril.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40018] = { id = 40018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreamleaf Sample", description = "The herb is brilliantly green, paper-thin, and somewhat sticky.\n\nYour herbalism trainer in Dalaran will want to see this.", completion = "I know this herb. I've seen it once before, in the Pandaria's Valley of the Four Winds.\n\nThis is dreamleaf.", objectives = "Bring the Dreamleaf Sample to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40019] = { id = 40019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Empathetic Herb", description = "Something is different about this dreamleaf, though. It is less than pure.\n\nI have a theory.\n\nThe wilds of Val'sharah have been blighted by a nightmarish curse. Sensitive herbs like this may be susceptible to such a blight.\n\nI need more information before I can draw any conclusions. Find me some healthy samples and some blight-infested samples, and we can continue.", progress = "Those poor plants...", completion = "It is just as I suspected. The infested herb is dying... but this may be turned to our advantage.\n\nLook, herbalist. The dying dreamleaf has swollen with herbaceous extract. While harvesting the healthy dreamleaf is trivial, you can harvest enormous amounts of product from the infested ones.", objectives = "Obtain 15 Healthy Dreamleaf and 5 Blight-Infested Dreamleaf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40020] = { id = 40020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted to Death", description = "The corruption has completely taken this herb.\n\nThis blight is a mysterious force whose complexities transcend the teachings of simple herbalism. An expert in such infestation will need to tell you what's really going on here.", completion = "Another plant, fallen...\n\n<The druid attempts to blink back tears, and fails.>\n\nDAMN YOU, NIGHTMARE! DAMN YOUUUUU!!!", objectives = "Find someone in Lorlathil to teach you about the blight's effects on herbs.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40021] = { id = 40021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Dead Plant is One Too Many", description = "We must exact VENGEANCE for this. While I understand the importance of the balance between the Emerald Dream and the Nightmare, this time it's corruption has gone TOO FAR!\n\nSatyrs. I blame the satyrs for this. Make them pay! Make them pay, and Elune will reward you with her bounty!", progress = "Exact your bloody vengeance, {class}. Show them the might of an herbalist.", completion = "I feel the blight subsiding. Good.\n\nOur respite will not last forever, but look... even now, the dreamleaf has succumbed more of its bounty.", objectives = "Slay 20 satyrs within Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40022] = { id = 40022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choked by Nightmare", description = "Another plant, killed by the blight. This one coiled so hard that it starved itself of sunlight.\n\nYou should bring it to Wildcrafter Osme in Lorlathil. He won't be happy.", completion = "<Osme looks at the herb.>\n\n<He is silent for a moment.>\n\nNOOOOOOOOOOOOOOO!!!!!!", objectives = "Bring the Blight-Choked Herb to Wildcrafter Osme in Val'sharah.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40023] = { id = 40023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Straw", description = "We cannot falter in our crusade against this corruption, {name}.\n\nIt is our duty as heroes. As herbalists.\n\nAs hero-balists.\n\nSlaying simple satyrs will not do. We must attack their leaders. Bring this fallen herb to Shala'nir, in the northeast. Find Tur'xoran's summoning stone, and place this herb in front of it. Then... rip off his head.\n\nDo it for the plants.", progress = "<The druid seethes.>", completion = "I thank you for your bravery, {name}.\n\nThe next time you approach a sprig of dreamleaf, you may just find that the land thanks you, too.", objectives = "Use Tur'xoran's Summoning Stone to summon and slay Tur'xoran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40024] = { id = 40024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foxflower Sample", description = "Something about this herb catches your eye... and your nose.\n\nYour herbalism trainer in Dalaran would certainly be interested in studying some samples of this piquant new flower.", progress = "<The tauren sniffs the air.>", completion = "I like this herb you've brought me, {name}. In a way, it reminds me a bit of the Gorgrond Flytrap: both of them have a habit of attacking your nose.\n\nLook. If you collect the herb this way, your yield should be a bit higher...", objectives = "Obtain 20 samples of Foxflower, then bring them to Kuhuine Tenderstride in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40025] = { id = 40025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teeny Bite Marks", description = "This herb has been chewed by some of the local wildlife.\n\nWhat kind of animal would eat foxflower? A bear?\n\nPerhaps your trainer in Dalaran will know.", completion = "You're right, {name}. Something has been chewing on this herb.", objectives = "Bring the Nibbled Foxflower Stem to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40026] = { id = 40026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chase the Culprit", description = "This is a powerful herb, {name}. Creatures will occasionally snack on some simpler herbs, but usually they avoid plants of such potency.\n\nI'm intrigued. What kind of animal would eat foxflower? A moose?\n\nYou should investigate further. Find out what creature has been snacking on foxflower, and then see if you can wrestle some of the flowers from its mouth, before it escapes.", progress = "Did you find out what was eating the foxflower? Was it a goat? A beaver? A nightsaber?", completion = "Foxes.\n\nHuh.\n\nThat... that makes sense. I suppose I should have guessed that.\n\nWell, now that I feel sufficiently stupid, let's look at these bits of flower, to see if there's anything we can learn...", objectives = "Find out what creature has been eating Foxflower, then chase it and catch 12 Chewed Foxflower Bits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40028] = { id = 40028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pied Picker", description = "As you finish gathering the foxflower, a particular part of the bloom catches your eye.\n\nOne of the leaves has a small protuberance, right where it meets the stem. Further investigation suggests that this is where the foxflower's unusual smell comes from.\n\nYour herbalism trainer would be interested in seeing this.", completion = "<Kuhuine sniffs the small gland.>\n\nThat's certainly a scent gland, alright. It seems to be mostly inert from an alchemical point of view... but I'd guess that this is what is attracting those foxes.\n\nExpress this gland when you can, and you may find yourself attracting a friend or two.", objectives = "Bring the Foxflower Scent Gland to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40029] = { id = 40029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fjarnskaggl Sample", description = "To one not trained in herbalism, this brambly bush might appear to be entirely useless. Your training, however, reveals this to be a very special plant indeed.\n\nYour herbalism trainer in Dalaran will want to see some more samples of this.", progress = "What do you have there, herbalist?", completion = "What a fantastic find, {name}. This must be the celebrated vrykul herb, fjarnskaggl. I've only read about it in books!\n\nHere, I'll share what I remember with you...", objectives = "Bring 20 Fjarnskaggl to Kuhuine Tenderstride in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40030] = { id = 40030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ram's-Horn Trowel", description = "The rune markings along the tool's grip suggest that it was left behind by a vrykul herbalist.\n\nApparently, the vrykul are also gathering this fjarnskaggl. Your trainer, Kuhuine, mentioned that she had read about this herb in the past.\n\nPerhaps she might be interested in seeing the tools that the vrykul use to harvest it.", completion = "You found this near a snarl of fjarnskaggl?", objectives = "Bring the Ram's-Horn Trowel to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40031] = { id = 40031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vrykul Herblore", description = "<Kuhuine studies the trowel further.>\n\nThis is a standard digging tool. There is not much to be learned here, except...\n\n...this DOES suggest that the vrykul are still actively gathering this herb.\n\nThe vrykul likely know much more about this herb than we do. All we need to do is find out where their knowledge is stored.", progress = "Any luck finding those books, {name}?", completion = "This book: \"Herblore of the Ancients\", seems promising, but several pages are ripped out. Shame.\n\nStill, there is much to learn in the others.\n\n<Kuhuine turns to a random page, flips a few pages back and...>\n\nSee, look at this technique here!", objectives = "Find three vrykul Herbology books in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40032] = { id = 40032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Page", description = "<The page appears to be ripped out of a larger book. It reads:>\n\n\"...the Cairn of the Sea, a place long-known to be beloved by the gods.\n\nHe placed his offering of fjarnskaggl at the foot of the cairn, mouthed the words 'Herbs beget herbs', and received the blessing he desired.\"\n\nThis may be related to the books you brought back to your herbalism trainer.", completion = "What good fortune! This page matches perfectly with the book you retrieved for me. We just need to piece them together, and...", objectives = "Bring the Runed Journal Page to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40033] = { id = 40033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fjarnskaggl", description = "There! It seems that there was a vrykul herbalist, Torgus, who brought a gift of fjarnskaggl to a seaside cairn - presumably in Stormheim - and by doing so received a blessing from his ancestors.\n\n<Kuhuine shrugs.>\n\nIt's worth a shot, though without knowing what you're getting into, you may want to bring friends with you.You will learn:", objectives = "Bring 20 Fjarnskaggl to the Wind-Worn Cairn in Stormheim, then earn the Blessing of Fjarnskaggl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40034] = { id = 40034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starlight Rosedust", description = "Despite all your training, the rose disintegrated in your hand.\n\nYour herbalism trainer in Dalaran will want to see this.", completion = "This herb just disintegrated in your hand?\n\nFascinating...", objectives = "Bring the Starlight Rosedust to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40035] = { id = 40035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gentlest Touch", description = "Sadly, I don't have any special techniques that can help you here. You'll simply need to practice your methods. Get back out there, and focus on a gentle touch when dealing with starlight roses.", completion = "Any success? None?\n\nEven if you haven't found success, your skills are improving. Don't give up, herbalist.", objectives = "Attempt to harvest 15 more Starlight Roses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40036] = { id = 40036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jeweled Spade Handle", description = "An immaculately carved spade handle lies beside the rose. Apparently the spade was more beautiful than it was durable, as the blade has completely fallen off.\n\nYour herbalism trainer may be interested in seeing this.", completion = "You say you found this near a starlight rose?\n\nYou adventurers, always finding such interesting things out there in the wilds...", objectives = "Bring the Jeweled Spade Handle to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40037] = { id = 40037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spade's Blade", description = "Did you notice the script along the base of the handle, {name}? It says \"Herbalist Tharillon,\" in the writing of the nightborne.\n\nThe handle does little for us, but perhaps the blade of this spade will give us some information on how to harvest the starlight rose without failing quite so often.\n\nI would start my search for it in Suramar.", progress = "How goes your search?", completion = "The blade is enchanted - of course it would be. I'm certain that we can replicate this enchantment here in Dalaran.\n\nShame that that herbalist wasn't more agreeable. There may have been more that we could have learned from him. At least he's still alive out there, somewhere...", objectives = "Find the Broken Herbalist's Blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40038] = { id = 40038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insane Ramblings", description = "Scribbled, angry phrases on a dirty scrap of vellum. One part catches your eye:\n\n     \"thinks <HE/SHE> knows how to gather herbs\n {name}{name}\n{name}{name}    steal my blade\n  slit <his/her> THROAT when I\n\n        just need\n      a bit more mana\n    maybe aethril, yes...\"\n\nYour herbalism trainer may be interested in seeing this.", completion = "My word. This person really hates you.\n\nSay - do you think this is written by that nightborne herbalist you... encountered?", objectives = "Bring the Scribbled Ramblings to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40039] = { id = 40039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tharillon's Fall", description = "He mentions your name... his blade... aethril...\n\nI'd say that this is absolutely from Herbalist Tharillon, and by the look of it, he may have succumbed to the plight of the nightfallen. Furthermore, if he's looking for aethril, he's probably in Azsuna somewhere.\n\nTharillon is currently our only hope for learning more about starlight roses. Seek him out, but you may want to bring friends... he likely won't go without a fight.", progress = "May the Earthmother walk with you, {name}.", completion = "Fantastic work, {name}! With this knowledge, we may never have to suffer a handful of starlight rosedust again!", objectives = "Bring 20 piles of Starlight Rosedust to Azsuna, use them to taunt Herbalist Tharillon out of hiding, then search him for information about herbalism.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40040] = { id = 40040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felwort Sample", description = "This herb bubbles and seethes with a foul energy. It is smooth, dry, and cool, yet somehow quite painful to touch.\n\nYour herbalism trainer in Dalaran will want to see this.", completion = "Oh. I don't like this herb at all. I'm fascinated, but I don't like it.\n\n<Kuhuine peers into the center of the plant.>\n\nLook at the size of these seeds, {name}. We can use these. Make sure you harvest them carefully next time.", objectives = "Bring the Felwort Sample to Kuhuine Tenderstride in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40041] = { id = 40041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felwort Analysis", description = "I sent felwort samples to some of my fellow herbalists, but haven't heard back from them yet. Could you please follow up with them and collect their analyses.\n\nRyno Bloomfield is currently working in Un'goro Crater.\n\nDani Earthtouch is researching Freya's influence in Sholazar Basin.\n\nFinally, Lohor has been working in the overgrown portion of Gorgrond.", progress = "Thank you for your willingness to travel, {name}.", completion = "Much of this is very technical and mundane, but Ryno's analysis can be applied right away.\n\nLook at this, here...", objectives = "Collect Ryno Bloomfield's Analysis, Dani Earthtouch's Analysis, and Lohor's Analysis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40042] = { id = 40042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Nightmare: Felwort Mastery", description = "I have a theory on how we can better harvest this felwort, {name}. You see, sometimes in order to understand how something comes into being, you have to work backwards.\n\nI've recently heard of the corruption of one of our greatest gods, Cenarius. I have no doubt the same corruption that lives in these herbs also resides within him now.\n\nIf you were able to cleanse that corruption, find a way to understand how it works and remove it, I think we can apply that to how we harvest these herbs.", progress = "I hope you bring some friends with you on this journey, for this may be your greatest lesson.", completion = "<Kuhuine carefully takes the seed from you and listens to your tale of Cenarius' cleansing.>\n\nFascinating! If what you're saying is true then that means we can harvest Felwort in a similar manner. Now listen...", objectives = "Travel to the Emerald Nightmare and cleanse Cenarius of his affliction. Bring back anything you discover to Kuhuine in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40043] = { id = 40043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter of Heroes", description = "Helya has made a mockery of my order by creating her own \"helarjar\", powerful undead tasked with hunting down heroic warriors and taking their souls before my val'kyr can claim them. Among them is her personal champion, Vigfus Bladewind, who wields stolen blades I forged myself long ago.\n\nHe has returned to Tideskorn Harbor with a full cargo of stolen souls to take to Helheim. Go there, kill him and his helarjar, and make the swords yours.", progress = "Ah, you have returned...", completion = "Curse Helya, she's corrupted the blades! Still, her champion defeated, her helarjar skulking back to Helheim, and my weapons in the hands of my chosen champion! She even made them more powerful than before. Wield them well, {name}, smite the enemies of this world!", objectives = "Deal with Vigfus Bladewind's warband and claim his blades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40044] = { id = 40044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadows in the Mists", description = "Many of the Kvaldir here in the bay are former denizens of this harbor, cursed by the sea-witch Helya to do her bidding for all time.\n\nThe ones you read about, they still walk the stagnant waters. They could be given respite, should a kind soul bring it to them at the tip of a blade.\n\nSo tell me, how kind is your soul?", completion = "Their toil is ended, and fewer kvaldir walk the lands of Stormheim.\n\nBoth are blessings, I would say.", objectives = "Defeat Captain Sten, Sigrid, Kjell and Halvir in Helmouth Shallows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40045] = { id = 40045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature vs. Nurture", description = "I appreciate murloc-kind far too much to tell you to go kill all the adults.\n\nWhat we should be doing is setting up the next generation to be more peaceful; Murky is the best representative for this. \n\nBring him to talk to the murloc tadpoles. He'll get them on our side.", progress = "Getting the support of the tadpoles is very important for our mission.", completion = "Murky's gained quite the following, hasn't he? Perhaps they can help him out.", objectives = "Talk to 10 Swamprock Tadpoles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40046] = { id = 40046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavenging the Shallows", description = "The kvaldir exist to spite Odyn, and it is here their spiteful work is done. They rob the souls of the living - the souls not yet judged - thus robbing Odyn of his champions.\n\nThey bring them here to transport to Helya, though the mists obscure any indications of how.\n\nYou seem to fare the mists well. Perhaps if you search the wreckage in the bay, the answer may present itself. You outsiders seem to have a knack for uncovering the most hidden of secrets.", progress = "Have you found answers, or more questions?", completion = "The Naglfar...\n\nSo Helya's kvaldir can navigate the mists?", objectives = "Search the Shipwreck Debris in Helmouth Shallows for Havi's clue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40047] = { id = 40047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'll Huff, I'll Puff...", description = "Murky is my favorite little fella. However, in order to lead a change in the murloc population here, he needs some awesome abilities.\n\nThere are a lot of pufferfish around in the water, and I think that they could be a good resource for him. \n\nKill a few and collect their eggs for Murky.", progress = "Pufferfish have this impressive ability of... exploding. They could be a powerful tool for Murky.", completion = "The pufferfish will be a perfect resource for Murky! I'll just whip up a spell to make them grow more quickly.\n\nAll he'll have to do is throw, then boom!", objectives = "Collect 5 Pufferfish Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40048] = { id = 40048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strings of the Puppet Masters", description = "I understand you were just here to deliver the vellums, but we could use your skills as a {class}. Our forces can only hold back the demon invasion, disallowing us to send anyone further into the enemy's camp.\n\nThe stronger of their forces stay in the back, commanding from a distance. They carry enchanted runes to keep control over the frontline demons.\n\nI would very much like to study one of these runes. Please retrieve one for me, so we may learn from it and use it against the Legion.", progress = "Have you found any runes yet?", completion = "Yes, this is it.\n\n<Jace turns the rune over in his hands, studying the intricate markings.>\n\nExcellent work, {name}. I'll make sure Nalthanis is made aware of your contribution.", objectives = "Acquire a Rune of Dominance from the demons at Legion Camp: Chaos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40049] = { id = 40049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slime Time", description = "Murky's a growing boy, he needs to eat! What better than slimeweed for a young murloc?\n\nThere's plenty of it around in the water amongst the murlocs; swim through it and feed Murky!", completion = "Murky seems to have gotten a very strong slime ability due to this slimeweed. Fantastic!", objectives = "Feed Murky 6 Bunches of Slimeweed by swimming through them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40050] = { id = 40050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipwreck Cove" }
quests[40051] = { id = 40051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Secrets", description = "The demons made a grave error inscribing their secrets into this book. The fel energy emanating from it is potent.\n\nBut there's only enough to enact one of the rituals. After that, the book will be consumed.\n\nIt's up to you to choose which secrets we want to use against the Burning Legion.", progress = "Have you made up your mind?", completion = "Surprising. I agree. Well chosen, {name}.\n\nNow, you must teach the rest of us.", objectives = "Read the Tome of Fel Secrets to choose between the Havoc and Vengeance specializations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40052] = { id = 40052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Vrykul Mastered", description = "Here are those tablets back, along with their deciphered writing. You can take this codex back to Pallin, too. I'll start getting my things ready for when he calls me back to Dalaran.\n\n<Nicholo sighs.>\n\nLearn from my example, {name}. If I were you, I'd break free from Pallin's \"requests\" as soon as you can.", completion = "So, Nicholo was able to complete the codex? And the tablets are deciphered!\n\nHmm... that's interesting. These tablets have some interesting spells that we could use to our benefit... although I find working with stone to be a bit archaic. I'll just put these down on parchment and let you test for any side effects.", objectives = "Return the tablets and codex to Professor Pallin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40056] = { id = 40056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our New Allies", description = "Student! Your fellow demon hunters in Azsuna have sent for you.\n\nI can certainly appreciate your time being spent fending off the Legion, but it doesn't excuse you from your studies.\n\nWhile you're down there, I'd like you to come up with some new glyphs for your abilities.\n\nSurely my genius has worn off on you and you'll be able to create your own recipes based on what you learn.", completion = "{name}, good to see you again. We could certainly use your strength.", objectives = "Report to Allari the Souleater in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40057] = { id = 40057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Price of Power", description = "I see, you wish to augment your powers through script. I believe we can kill two birds with one stone then.\n\nI need help here reducing the demon threat. Perhaps some more engagement with our enemy will inspire you.", completion = "I wish I had more like you, {name}. You fight with a great passion.\n\nAnd I see you also learned a bit more about how to augment our abilities. I'm sure your master in Dalaran will be pleased.", objectives = "Slay 15 demons to help lessen the invasion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40058] = { id = 40058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defense Symbology", description = "As you know, {name}, we demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves.\n\nUp to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. He could use your assistance with his ritual.", completion = "You've come to help me with my ritual? I thank you, {name}.\n\nIn this time, allies are more important than ever.", objectives = "Find Baric Stormrunner near the Ley-Ruins of Zarkhenar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40059] = { id = 40059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opposites Repel", description = "The ruins nearby have had an eruption of ley energies. Twisted night elves deemed \"Nightfallen\" are scavenging the area as we speak.\n\nCollect ley dust for me from the nightfallen in the ruins up ahead. The dust is infused with arcane energy that I'll need to complete my ritual.", progress = "Even though they are opposites, one can not exist without the other.", completion = "If you can believe it, that was the easy part.\n\nThe next part will be a bit more challenging, at least for me it will.", objectives = "Collect ley dust from the nightfallen in Zarkhenar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40060] = { id = 40060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containing the Demon Within", description = "Now that we have all the essential pieces, let's begin the ritual.\n\nI'll instruct you on how to help me throughout it. It is pivotal that you follow my instructions when I give them, or the ritual will fail.", completion = "It is done. I fear that I had waited any longer to improve my wards, the demon in me may have taken over.\n\nThank you again, {name}.", objectives = "Assist Baric in completing the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40061] = { id = 40061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Know Your Enemy", description = "As we fight the demons, we've also been studying them.\n\nGreat understanding can come from gathering intel. I have a demon hunter near the Felblaze Ingress now gathering intel on the demons there.\n\nGo to her and see what she has learned from the demons invading that region.", completion = "Good to see you again, {name}. Kayn has sent you to see what I have learned?\n\nIn that case, I have much to tell.", objectives = "Find Zaria Shadowheart near the Felblaze Ingress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40062] = { id = 40062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bulging Nightmare Pod", description = "<The flower has folded inward, to protect itself from the nightmare energy trapped within.>\n\n<Professor Pallin would be interested in seeing this.>", completion = "Pods like this contain tremendous amounts of energy. Milling one incorrectly can be catastrophic to the front of one's robes.\n\nLearn to mill them correctly, though, and you can dramatically increase your milling speed. Watch and learn, student!", objectives = "Bring the Bulging Nightmare Pod to Professor Pallin in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40063] = { id = 40063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Control is Key", description = "I trust you remember why you removed your eyes?\n\nEven though we can see more clearly now, the demons have found ways to mask even their fel energies from us.\n\nA demon commander walks amongst the troops below, commanding them from the shadows. His cloak is powered by an energetic crystal.\n\nFind and destroy that crystal, then kill the commander.", completion = "I commend you, scribe. You are an excellent hunter.\n\nTake this ink as payment for your efforts. I have no need of it.", objectives = "Destroy the crystal providing protecting Overseer Felorax, then slay him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40064] = { id = 40064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woody Seed Cluster", description = "<Attempting to mill this flower has proven more difficult than usual. Located in the bushy center of the bloom is a densely-packed cluster of seeds.>\n\n<Professor Pallin would be interested in seeing this.>", completion = "This came from a foxflower? Fascinating.\n\nYou know, we can use these woody cores to our advantage. If you mill a woody flower along with several softer flowers, you can speed up your process dramatically! Watch this...", objectives = "Bring the Woody Seed Cluster to Professor Pallin in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40065] = { id = 40065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fjarnsk", description = "<A goopy substance seeps from the interior of the bloom. It's not ink... it is something else entirely.>\n\n<Professor Pallin would be interested in seeing this.>", completion = "<The Professor dips his finger into the fluid and tastes it.>\n\nOh! I know what this is. The herbalists were talking about this. It's called fjarnsk.\n\nYou know, stranglekelp often contains pockets of fluid not unlike this. Let's see if we can carry an old milling technique forward...", objectives = "Bring the Fjarnsk to Professor Pallin in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40066] = { id = 40066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 032 - Blackbeak Overlook - twh" }
quests[40067] = { id = 40067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Vignette: Boulderfall - twh" }
quests[40068] = { id = 40068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Vignette: Egyl the Enduring - twh" }
quests[40069] = { id = 40069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fledgling Worm Guts", description = "The drogbar use these caves as a place to train fledgling worms.\n\nThe rockcrawlers are young and fairly weak, for now, but in time they will grow in size and strength. Without our intervention, the worms will morph into the monstrosities that the drogbar ride into battle.\n\nTheir guts are also known to be quite useful, and I have need of them. Two worms, one stone.", progress = "What are their guts for? Well, you'll see. You might not like it, but you will soon find out.", completion = "Those worm guts will be perfect for a special sort of rope.", objectives = "Collect Worm Guts from Fledgling Rockcrawlers within Rockcrawler Chasm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40070] = { id = 40070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eagle Egg Recovery", description = "Eagles are revered by the Skyhorn tribe, but their numbers are dwindling.\n\nThe drogbar feed their fledgling worms eagle eggs so they'll grow strong enough to ride into battle. \n\nIf the drogbar continue to pilfer these eggs, the eagles may become extinct.\n\nHead deeper into the cave and recover any eagle eggs you can find.", progress = "If the pilfered eggs are not recovered, the eagle may go extinct.", completion = "These eggs are in poor condition, {name}. Some are cracked and spoiled, while others are cold to the touch.\n\nYet there is still hope. I believe a few of the eggs you recovered can be saved.", objectives = "Head into Rockcrawler Chasm and recover eagle eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40071] = { id = 40071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tamer Takedown", description = "The drogbar will continue to breed vicious worms as long as their tamer lives. \n\nKorgrul is responsible for turning fledgling rockcrawlers into the monstrous siege worms that are ridden into battle.\n\nHead deep into the chasm and end his life, so that we may also see the end of these unnatural creatures.", progress = "Put an end to Tamer Korgrul, so that we may also put an end to the training of siege worms.", completion = "Korgrul deserved his fate. Thank you, {name}.", objectives = "Kill Tamer Korgrul within Rockcrawler Chasm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40072] = { id = 40072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: Securing the Aegis", description = "The Felskorn may be broken, but the head of the beast yet lives. The God-King will still vie for the Aegis if left unchecked.\n\nYou, who have completed trials upon trials, must not let this come to pass. You must claim the Aegis over Skovald's broken bones!\n\nThe Halls of Valor await!", completion = "With the God-King's defeat, the Aegis of Aggramar is yours to claim.", objectives = "Defeat God-King Skovald in the Halls of Valor and claim the Aegis of Aggramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40073] = { id = 40073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pugg" }
