quests[40077] = { id = 40077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Invasion Begins", description = "Our advance force of demon hunters is here and has engaged the Legion.\n\nMake our presence known. Let's send a shiver down every demon spine. Raise our colors with pride, {name}.", completion = "That ought to get their attention.\n\nNow, onto the business of summoning in the rest of our forces.", objectives = "Slay 15 demons and change the Legion banner to take control of Despair Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40078] = { id = 40078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Heavy Burden", description = "With Ashildir's judgment, your final trial is complete. \n\nBut even Valhallas can wait, for now we must eat! Being dead works up quite an appetite.\n\nCome now, bring some of that fish to roast over the fire. It is far too heavy for me to carry.", completion = "It is clear that your cooking prowess is only matched by your might in combat. \n\nNow, on full bellies, we ride to Valhallas!", objectives = "Take the fish from Havi's Fish Barrel and skewer it on the spear above the fire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
