quests[40102] = { id = 40102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocs: The Next Generation", description = "The time has come! Murky and his followers need a place to hide out and train--away from the mature murlocs--so that they can prepare to take over in the future.\n\nThere's a nice cave not too far away... only problem is that it's filled with makrura.\n\nThis would be a good base for the tadpoles. Murky must go show them what for!\n\nMindmeld with Murky in his egg and show him how it's done!", progress = "These young murlocs show such promise. They'll do this shore good.", completion = "This cave will make a great base for the young tadpoles!", objectives = "Mindmeld with Murky and slay 10 Cavemoss Clackers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
