quests[40112] = { id = 40112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huln's War - Malorne's Favored", description = "[In broken Common] Shan'do ask for you. Sent Eche'ro beast with message on rack.\n\nUnng Ak hear Eche'ro sound fighting. You find beast? Give help, maybe feathered night elf be relieve.", completion = "<Eche'ro looks up briefly, then lowers its head before you. This creature is thankful for your aid.>", objectives = "Rescue Eche'ro.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40113] = { id = 40113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Grrvrgull the Conquerer" }
quests[40114] = { id = 40114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prephoof Compound Treasure" }
quests[40115] = { id = 40115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepfoot Compound Treasure" }
quests[40116] = { id = 40116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prephoof Compound Treasure" }
quests[40120] = { id = 40120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Murky Fate", description = "You may not know, but you stand upon the grounds of Morheim, home to the greatest warriors of the land. Our deeds were great, our valor legendary. It pains me that we see such an end.\n\nThe creatures set upon us at nightfall. Our men fought bravely, but were vastly outnumbered. Now their corpses lie rotting in the sun, with no burial and no rites.\n\nThis is not an end befitting to the glorious warriors of Morheim. Make it right, and you will have our thanks.", progress = "Have you done this task?", completion = "It is good to know that our warriors remains have been honored.\n\nMay they now celebrate their victories in the halls of Valhallas.", objectives = "Use the Smoldering Torch to burn 8 Decaying Corpses in Morheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40121] = { id = 40121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ley Line Influences" }
quests[40122] = { id = 40122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarius, Keeper of the Grove", description = "Ahh, Val'sharah.\n\nIt has been an age since I have set foot in these sacred woods. Too long...\n\nOur work here is simple, {class}. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras' Tomb and thwarting the Legion.\n\nYou have many treacherous tasks in front of you. Consider your visit here a brief respite.\n\nCome, this will not take long.", progress = "Cenarius!", completion = "This corruption - I've never seen it before.\n\nAnd yet, it seems somehow familiar...", objectives = "Speak to Malfurion Stormrage at Lorlathil in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40123] = { id = 40123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightborne Pact", description = "<Thalyssra winces and holds her abdomen.>\n\nNgh... I can ignore this wound no longer.\n\nHelp me patch this up. I will explain everything.", completion = "We must find a way to reclaim Suramar City.", objectives = "Bandage Thalyssra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40124] = { id = 40124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gift of the Storm Cooldown" }
quests[40125] = { id = 40125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Branch of the Arcan'dor", description = "You have used the spellstone of Kel'danath to soothe countless withered. Yet it contains merely a shade of the arcan'dor's power, drawn from its slumbering seed. \n\n<Thalyssra holds aloft a gleaming white branch.>\n\nThis fell from the tree. Though it is severed, it is not dead - invisible threads of magic bind all pieces of the arcan'dor together.\n\nI have enchanted this branch with a new iteration of Kel'danath's charm spell. With it, you can mend the arcane essence of even more withered. Use it well.", completion = "I never imagined I would spend my time in exile studying withered. Through them, I have learned a great deal about my own people, and the nature of our relationship with the Nightwell.", objectives = "Speak with Thalyssra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40126] = { id = 40126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Grelda" }
quests[40127] = { id = 40127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da-Nel's Quest" }
quests[40129] = { id = 40129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repairing the Source", description = "<A glint catches your eye in the dirt. A brief excavation yields a mostly intact piece of an arcane construct's power core. The breaks appear to be clean, perhaps you could repair it if you find the other fragments.>", objectives = "You have found a damaged power core for an arcane construct. It seems like you could repair the device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40130] = { id = 40130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Washed Clean", description = "Mighty though the Legion is, theirs is not the strongest power in Azeroth.\n\nThere is a place where Enchantress Ilanya and I spent many blissful hours together. The love that infuses such a place is more potent than fel magic, {name}.\n\nGo to the Nor'Danil Wellspring. Its waters can purify the fel dust you have collected... and perhaps purify me as well.\n\nI will meet you there.", progress = "It... it worked! I am myself again at last!", completion = "The demon I was is no more. I believe I am ready to return.", objectives = "Meet the Fallen Priestess at the Nor'Danil Wellspring. Watch as the priestess attempts the purification ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40131] = { id = 40131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonehide Leather Sample", description = "The quality of this leather scrap appears representative of the beast hides found in the Broken Isles.\n\nYour skinning trainer in Dalaran would be interested in seeing this.", progress = "How may I help you?", completion = "Greetings, {name}. What have you brought for me today?", objectives = "Bring the Stonehide Leather Sample, along with 10 additional pieces of Stonehide Leather, to Kondal Huntsworn in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40132] = { id = 40132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In One Piece", description = "<Your trainer looks over the hide.>\n\nThis hide is usable, but it is mournably small. You disrespect the beast by chopping it up like this, {name}. You make light of the gift that it gave to you.\n\nGo out into the wilds again. Skin the leathery beasts below us, and this time, bring me hides in one piece.", progress = "<Kondal sternly watches you approach.>", completion = "Mm. This is better.\n\nKeep my advice in mind the next time you take out your skinning knife.", objectives = "Obtain 20 Undivided Hides by skinning the beasts of the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40133] = { id = 40133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrap of Pants", description = "The mouth of this particular beast contained a piece of handsewn cloth. The fabric bears the word \"singwa\".\n\nWhile the term \"singwa\" is unfamiliar, it DOES happen to be the middle of the last name of a fairly notable Azerothian skinner.", completion = "Ye found me extra set o'pants!", objectives = "Bring the Scrap of Pants to Hemet Nesingwary in Highmountain.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40134] = { id = 40134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highmountain Hides", description = "So, ye're a skinner too, aye?\n\nThat's great news, {name}! I don't think I ever knew we shared that in common.\n\nYe've GOT ta see some o'the hides we've got here in Highmountain. Why, I'd give me spare monacle just t'get me hands on some o'those fine, silky hides...", progress = "<Hemet looks lustfully at the horizon.>", completion = "Y'got these fer me, laddie? I... I don't know what ta say!\n\nHere, take this. It's the least I can do.\n\n<Hemet buries his nose deep into the bear hide.>", objectives = "Obtain 5 Bear Hides, 5 Elderhorn Hides, and 5 Saber Hides by skinning the creatures of Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40135] = { id = 40135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Freedom to Roam", description = "I remember bein' young, {name}. D'ye remember it? So much less responsibility... I could just run around as I pleased. Now, I'm pretty much stuck with my hunting crew, here in Highmountain.\n\nThere're so many interestin' creatures in the other regions o'the Broken Isles, though. I'll mark yer map, you get out there and do some skinnin'!", progress = "Once ye're done, I'll show ye a trick or two.", completion = "These are marvelous, {name}. Well done.\n\nI can show ye how t'get better results from yer skinnin'. Take a look at this wolf hide, here...", objectives = "Obtain 5 Musken Hides, 5 Lion Seal Hides, 5 Boar Hides, and 5 Wolf Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40136] = { id = 40136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immaculate Stonehide Leather", description = "You have been skinning for a long time now, but never have you seen a leather specimen as fine as this. Durable, pliable, beautifully colored...\n\nYour trainer in Dalaran would be VERY interested in seeing this.", completion = "{name}, you return. What can I do for you today?", objectives = "Bring the Immaculate Stonehide Leather to Kondal Huntsworn in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40137] = { id = 40137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leather for Ske'rit", description = "This hide certifies that you have learned everything about leather that I can teach you, {name}. My skills have dulled since I set up shop here in town.\n\nI have a former protege who skins the creatures of Suramar. His name is Ske'rit. His skills remain as sharp as his blade, and if there is anyone out there who can teach you, it is him.", completion = "Ey dere. You be a skinna'?", objectives = "Report to Ske'rit in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40138] = { id = 40138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Crusader: Hides of Legend", description = "Ya, I can train you. Ting is, I'm still workin' on my techniques 'ere in Suramar. In fact, you can probably help.\n\nI need ta look at a few special skins, for comparison. I need a strong white yeti pelt, a really big demon skin, and da thickest direhorn skin you can find.\n\nDo that, and I'll share my results with you and' ol' Kondal up in de city.", progress = "Any luck findin' dose hides?", completion = "Ya gone and outdid y'self. Look at dese hides, bruddah!", objectives = "Obtain the Hide of Icehowl from the Trial of the Crusader.\n\nObtain the Hide of Occu'thar from Baradin Hold.\n\nObtain the Hide of Horridon from the Throne of Thunder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40139] = { id = 40139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: The Hide of Fenryr", description = "While you be here, I got a favor t'ask you.\n\nI been hearin' whispers about one big, nasty wolf dat's been causin' all kinds of trouble up in de vrykul lands. His name be Fenryr.\n\nI want his hide.", progress = "Is it done? Let me see it!", completion = "I seen wolf hides before, but dis be sometin' else.", objectives = "Obtain the Hide of Fenryr by skinning Fenryr in Valhallas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40140] = { id = 40140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ske'rit's Leather Handbook", description = "An' wit dat, my research be done.\n\n<Ske'rit hands you a scroll casing.>\n\nDis is what I been workin' on here in Suramar. Bring it to Kondal, so dat he can teach it to all you other skinnahs.\n\nSince you been helpin' so much, I put your name on it, {name}. Hope you don't mind.", completion = "You've returned, and with Ske'rit's book, I see.\n\nLet's look through this together, {name}...", objectives = "Bring Ske'rit's Leather Handbook to Kondal Huntsworn in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40141] = { id = 40141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormscale Sample", description = "This scale shimmers with electrical energy.\n\nYour skinning trainer in Dalaran would be interested in seeing this.", completion = "Yes, skinner?", objectives = "Bring the Stormscale Sample to Kondal Huntsworn in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40142] = { id = 40142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Core of the Stormscale", description = "Ahh, yes. The elusive stormscale.\n\nI have seen similar scales in Northrend, and some in Skywall, but it would appear that such a scale is common here. My colleagues that specialize in mail armor will be happy to learn this.\n\nTo more efficiently harvest this type of scale, you must first understand its power. Look for broken, unusable scales on your quarry, and remove the sparks within them. Once you have seen the sparks, you will better understand the stormscale.", progress = "Have you seen the sparks?", completion = "Very good, {name}. Greater understanding of the stormscale leads to more efficient skinning, which in turn leads to fewer unnecessary animal deaths.", objectives = "Obtain 20 Stormscale Sparks by skinning scaled creatures in the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40143] = { id = 40143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Treatise on the Properties of Stormscale", description = "Tucked between the folds of this animal's hide, you find a scrap of paper. It appears to be a handwritten guide to harvesting stormscales, but too much of the manuscript has been lost to be of use.\n\nPerhaps your skinning trainer in Dalaran could help you find its owner.", completion = "<Kondal looks over the paper, brows furrowed.>\n\nI know of only two people who may have written this, {name}. I can tell you where they both are located, if you so desire.", objectives = "Bring the Unfinished Treatise on the Properties of Stormscale to Kondal Huntsworn in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40144] = { id = 40144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glielle", description = "One skinner makes the wilds of Azsuna her home. Her name is Glielle, and she is a night elf - or at least, she was, in life.\n\nPerhaps the scroll was hers.", completion = "What? No, that scroll isn't mine. I don't do much writing these days.", objectives = "Find Glielle in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40145] = { id = 40145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Down", description = "I can train you, though.\n\nEveryone knows about the bright stormscales on the hippogryph's hindquarters, but did you know that they also have a few scales beneath their feathers? You just need to know where to look.\n\n<The night elf spirit indicates a few places near the hippogryph's wing joints.>\n\nNow go see if you can get some on your own.", progress = "Remember to check the entire beast, not just what's visible on the surface.", completion = "Looks like you've got the hang of it. Well done.", objectives = "Obtain 20 Hippogryph Scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40146] = { id = 40146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seymour and Agnes", description = "The other skinner - pair of skinners, to be honest - that comes to mind when you show me this scroll is a student of mine, named Seymour, and his mother Agnes.\n\nLast I heard, they were in Stormheim, hunting the storm drakes.", completion = "Yes, yes, that's my manuscript, but there's no time for that.\n\nLook what they've done to my MOTHER!", objectives = "Find Seymour in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40147] = { id = 40147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mother's Prized Knife", description = "The other day, Mother and I were up at the top of the nearby mountain, and she threw her skinning knife at me because the view wasn't good enough.\n\nHer knife is still up there, somewhere. I'd feel horrible just leaving it.", progress = "Mother always wanted to live long enough to see me die. Why did this have to happen!?", completion = "This is it - look, you can still see some of me on it.", objectives = "Obtain Agnes' Skinning Knife.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40148] = { id = 40148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red-Eyed Revenge", description = "It came out of nowhere. I was waiting for mother to finish skinning her half of the drake when the biggest storm dragon I'd ever seen came and... and...\n\n<Seymour finds his resolve.>\n\nI want you to kill as many of them as you can. Skin them, don't skin them, I don't care. Just get revenge for mother!", completion = "Thank you. I don't know why, but your murder spree helps me feel a little bit better.", objectives = "Slay 15 Adult Squallhunters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40149] = { id = 40149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drakol'nir Must Die", description = "The dragon that took Mother's life was named Drakol'nir.\n\nMother always wanted to wear his scale as a pendant, but we never got a chance to skin him because I couldn't kill him alone, and she didn't care much for killing. Only skinning.\n\nYou... you wouldn't mind bringing it for her, would you?", progress = "Even if I COULD have killed Drakol'nir, I never would have been able to drag him all the way down here.", completion = "<Seymour places the scale lovingly upon his mother's chest. Even in death, she seems to disapprove.>\n\nThank you, {name}. Here, you take her skinning knife. It's not much, but she won't be needing it anymore.", objectives = "Obtain the Scale of Drakol'nir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40151] = { id = 40151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immaculate Stormscale", description = "You have been skinning for a long time now, but never have you seen a scale specimen as fine as this.\n\nYour trainer in Dalaran would be VERY interested in seeing this.", completion = "What do we have here, {name}?", objectives = "Bring the Immaculate Stormscale to Kondal Huntsworn in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40152] = { id = 40152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scales for Ske'rit", description = "Your skills surpass mine, {name}. I have never even SEEN a scale such as this... let alone remove one so expertly.\n\nIf you still wish to learn more, you will need to seek an even greater skinner than I. His name is Ske'rit, and he was once my student.\n\nYou will find him in the wild areas of Suramar.", completion = "What do we got here?", objectives = "Find Ske'rit in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40153] = { id = 40153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Karazhan: Scales of Legend", description = "I know a ting or two about scales, but I'm losin' my edge. I been starin' at stormscales so long, I be forgettin' what de other kinds look like.\n\nI need ta look at a few special scales, for comparison. I need a nether dragon scale, a nice hot black dragonscale, and da thickest piece o' insect chitin you can find.\n\nGotta get dese stormscales outta my head, bruddah.", progress = "You been gone a while. You get de scales?", completion = "Dese'll do, skinnah.\n\nDese'll do.", objectives = "Obtain the Scale of Netherspite from Karazhan, the Scale of Sartharion from the Obsidian Sanctum, and the Scales of Garalon from the Heart of Fear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40154] = { id = 40154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of Azshara: The Scales of Serpentrix", description = "I got ta ask you a favor.\n\nI haven't been ta Azsuna, and I don't see myself leavin' Suramar anytime soon. Problem is, dere's a big ol' serpent out dere dat's just beggin' ta be skinned. Just BEGGIN' for it.", progress = "You got dis, skinnah.", completion = "Very nice. You got a good knife hand, {name}.", objectives = "Obtain the Scales of Serpentrix by skinning Serpentrix in the Wrath of Azshara dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40155] = { id = 40155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ske'rit's Scale-Skinning Suggestions", description = "Now dat I got all dese scales, I tink I know what I need to know.\n\n<Ske'rit hands you a few pages of handwritten notes.>\n\nHere's my latest findin's on stormscales. Bring 'em to Kondal, an' read through em' togethah.", completion = "You've been working together with Ske'rit? I should've known. You two are cut from the same hide.\n\nLet's see what he has written here.", objectives = "Bring Ske'rit's Scale-Skinning Suggestions to Kondal Huntsworn in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40156] = { id = 40156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felhide Sample", description = "This demonic hide is completely unlike any standard beast hide you are accustomed to.\n\nYour skinning trainer in Dalaran would be interested in seeing this.", completion = "I know very little about demonic hides, {name}. I prefer to stay away from them.\n\nThat said, I will share with you what I do know...", objectives = "Bring the Felhide Sample to Kondal Huntsworn in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40157] = { id = 40157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unseemly Task", description = "I'm quite impressed with what you've been able to skin in these lands, felhide in particular.\n\nBut as my knowledge is limited in this area of skinning, I know of one who may have increased his skill in skinning such beasts.\n\nYou can find my old apprentice, Ske'rit in Suramar. Ask him if he knows how to yield better results from skinning demons.", completion = "What'cha be needin' from me, mon?", objectives = "Find Ske'rit in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40158] = { id = 40158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkheart Thicket: Demons Be Different", description = "Oh yes, I've seen me fair share of demons while in dese lands. And skinnin' dem ain't no easy task.\n\nTheir hides are tougher than normal animals, fibrous, see? But if you be wantin' to make da most of their skins, den ya need to be practicin' more.\n\nThere be a creature I've heard of in da Darkheart Thicket whose hide's as tough as a demon's. When ya go ta skin him, try cutting with da grain in one even stroke.\n\nBring me his skin to show me you be picking up on what I'm sayin'.", progress = "Any luck on gettin' dat skin?", completion = "<Ske'rit takes the hide from you and looks it over.>\n\nYou definitely got da hang of it, bruddah.", objectives = "Go to Darkheart Thicket and kill Dresaron. Skin him and bring his hide back to Ske'rit in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40159] = { id = 40159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Nightmare: The Pestilential Hide of Nythendra", description = "There is one more demon hide to gather... but it isn't that of a demon. It's a dragon.\n\nNythendra, great green dragon, has nearly been eaten up by the Nightmare. Only a master skinner would be able to remove what bits of bug-eaten hide remain on her body.\n\nGo on then, {name}. Show me what you've learned.", progress = "Any luck with the dragon?", completion = "You have done it, {name}. You've earned the last of my knowledge.\n\nNow get out there, and get skinning!", objectives = "Obtain the Pestilential Hide of Nythendra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40160] = { id = 40160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magic Clams", description = "<The clam resonates with a arcane energy.>\n\nWhat are murlocs doing with arcane clams?\n\nPerhaps your Nightfallen allies could make use of them.", objectives = "Collect Infused Clams from Seerspine murlocs in the Murloc Shoals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40161] = { id = 40161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tapping the Underground", description = "Have you seen them, {name}?\n\nThese are not ordinary murlocs. They have been drawn by the ley line that flows from Azsuna into this land. \n\nSomehow they have managed to tap into its arcane current and are tapping its power for their own devious purposes.\n\nThese disturbances must be stopped if the ley line is to remain intact.", objectives = "Destroy Seerspine Conduits in the Murloc Shoals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40162] = { id = 40162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snowblind Mesa Treasure" }
quests[40163] = { id = 40163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snowblind Mesa Treasure" }
quests[40164] = { id = 40164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[40166] = { id = 40166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leying with Murlocs", description = "I have seen these Seerspine summon minor elementals, which is no small feat for a murloc, but their high summoner, Blargrrrl, is trying to summon Torretus from the river.\n\nI doubt a mere murloc has the capabilities to control an entity as powerful as Torrentus.\n\nBlargrrrl will be deeply entranced if he is trying such a feat. We'll need something powerful to halt his ritual.\n\nInfuse yourself with ley energies and return to me.", objectives = "Infuse yourself with ley energies located in the Murloc Shoals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40167] = { id = 40167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Story of Huln", description = "You work to unite the tribes. That is no small task. It has only been done once before in the history of this mountain.\n\nHuln Highmountain last united the tribes thousands of years ago to take on the Legion during the War of the Ancients.", progress = "The history of this place extends beyond our limited memory.", completion = "You have seen only a taste of what Huln Highmountain accomplished during his lifetime. Let us delve deeper into the past...", objectives = "Speak with Spiritwalker Ebonhorn to learn about Huln Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40168] = { id = 40168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Swirling Vial", description = "As you touch the vial, your mind is flooded with memories, not all of which are your own. The most vivid is a memory of exchanging a similar vial with someone in Shattrath, with A'dal's light shining behind you. Despite your best efforts however, you can't pinpoint when that might have been - maybe it hasn't been, and is yet to be?", completion = "Oh, interesting! \n\n<Cupri quickly grabs the vial and studies it intensely.>  \n\nPerhaps Zeph was right to keep investigating here. This vial certainly didn't originate from any currently known timeline. Most curious! Thank you for bringing it to me. Or did you already bring it once before?", objectives = "Bring the Swirling Timewarped Vial to the central dome in Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40169] = { id = 40169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crossroads Rendezvous", description = "An old apprentice of mine left during the war, shortly before we were all cursed.\n\nI've recently heard that she's been seen near the Felblaze Ingress. I would very much like to speak to her once more.\n\nGo and find her. Take her journal to her and let her know that I don't blame her for what she did.\n\nAnd if she's willing, please bring her back to me.", completion = "<The satyr takes the journal you offer and sobs.>\n\nYou bore the book of someone lost long ago, stranger. Better that you leave me in my misery than linger in this fel-cursed place.", objectives = "Search for signs of the priestess near the Felblaze Ingress.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40170] = { id = 40170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amateur Hour", description = "The hunters' lodge has attracted a lot of amateurs who call themselves hunters. They're scarin' away all the prize game with their antics.\n\nWhile I'm a known expert with my rifle, I've yet to manage the art of negotiation.\n\nHow about ya do us all a favor and tell those novice hunters to head for the hills?", progress = "Have those amateur hunters scattered? Don't be afraid to use your fists if words don't do the job.", completion = "Ya seem to have a gift when it comes to dealin' with amateurs. Maybe ya can help my ghostwriter, Addie?\n\nI've promised to teach her how to hunt, but I don't have time to show her the basics.", objectives = "Confront Amateur Hunters within Pinerock Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40173] = { id = 40173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unstable Prism", description = "As the prism struggles to stabilize in a single time flow, it bleeds a shadowy chill, the likes of which you haven't felt since Northrend. Surely some mage in Dalaran would be interested in this relic.", completion = "Let me see that. \n\n<Auzin ponders the prism for a while, before turning back to you.>\n\nHmm... Cupri could run tests on this for an eternity. This certainly qualifies as further evidence of meddling by a third party... or is it a sixth party...\n\nDo you mind if I keep it?", objectives = "Deliver the Frigid Timewarped Prism to an interested mage in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40175] = { id = 40175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleeping Bear" }
quests[40176] = { id = 40176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Head to Toe", description = "You've been busy, {name}. And you have some new patterns in your repertoire, I see!\n\nHow about we add another?", progress = "I'm very excited to see how this turns out.", completion = "I'm still amazed at how easily this leather takes shape. It's so flexible, yet keeps its strength.\n\nI think from here you can take my pattern and make it your own.", objectives = "Craft a pair of Sturdy Stonehide Boots.\n\nYou will need to use Namha's Tanning Rack and Namha's Workbench, located in Legendary Leathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40177] = { id = 40177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leather Lady", description = "I'd like you to start working with my apprentices.\n\nThe first is Diane Cannings, who has focused her expertise on the softer leather armors. She's just not that into mail armor, like the twins are.\n\nGo talk to her about this new type of leather.", completion = "You're the one Namha's been talking to. Pleased to meet you.\n\nHopefully we can expand our pattern list beyond the helm you've made.", objectives = "Meet with Diane Cannings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40178] = { id = 40178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vestment Opportunity", description = "While the vrykul of Northrend wore strong armor, their craftsmen always had the strongest.\n\nGo to Stormheim, search for someone who knows about leather armor, and bring their chest piece back to me.", progress = "How's your search going?", completion = "<Diane examines the chest piece thoroughly.>\n\nThis has some very interesting design. I think we can easily copy what they've achieved with this piece.\n\nHere, try this pattern out.", objectives = "Obtain a Hideshaper's Vestment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40179] = { id = 40179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormheim Savagery", description = "There's a land below - Stormheim, they call it - that's inhabited by vrykul. I remember the vrykul from my days in Northrend.\n\nWhat I remember most was how well-crafted their armor was.\n\nIf the vrykul here are as skilled as the ones in Northrend, then I'm certain we can learn something by studying their armaments.", progress = "Are the vrykul giving you much trouble?", completion = "Well now, this is a good variety of equipment you've brought me. Let's see what we have here...\n\n<Diane studies the armor pieces very carefully for a while.>\n\nLook here, {name}. See how they've strengthened the leather by over-stitching the seams...", objectives = "Obtain 7 Vrykul Leather Bindings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40180] = { id = 40180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mail Men", description = "The two dwarves behind me are the Glowergold brothers. They're my resident mail armor experts.\n\nWhile Ranid has decided to focus his skills towards lining his pockets, his brother, Thanid, still enjoys the crafting side of the trade.\n\nIntroduce yourself to Thanid. You may work with him to further our knowledge of turning these stormscales into something extraordinary.", completion = "Pleasure to meet ye! Now, I'll be needing ye to do one very important thing fer me.\n\nIgnore anything me brother tells ye. He's been out of practice fer years, but still thinks he's better than me.\n\nIt's a lie, lad.", objectives = "Meet with Thanid Glowergold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40181] = { id = 40181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Bandit", description = "I've heard rumors of a grand castle in Val'sharah that's known to house an impressive army. Surely, the armor they wear ain't made of sticks and hay.\n\nI'm willing to bet they've fashioned some mail armor at some point fer their troops and it's just sitting there, ripe for the taking.\n\nHow about ye head over there and see what ye can \"borrow\" from their armory.", progress = "Make sure ye don't get captured now, lad.", completion = "I knew ye had it in ye! Good work, lad.\n\n<Thanid looks the pieces over with a careful eye.>\n\nVery clever. The elves certainly know their trade.\n\nWe should be able to copy this method with little to no problem.", objectives = "Obtain 5 pieces of Black Rook Armor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40182] = { id = 40182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Good To Pass Up", description = "All types of Black Rook Hold armor are intriguing, but I'm most interested in their chest pieces.\n\nIf ye can, try to find someone of importance there and... relieve them of their shirt.\n\nIf it makes ye feel any better, I've heard they're all cursed, so puttin' them out of their misery is the least ye could do.", progress = "Chest armor is the best armor, I always say!", completion = "Oh, this is a beauty. Just look at that craftsmanship.\n\n<Thanid looks the piece over very carefully.>\n\nAnd looking at how it's pieced together, this should be a snap to replicate.\n\nHere, lad, give this pattern a try and see how that works for ye.", objectives = "Obtain a Black Rook Hauberk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
